solutionCode:
def rob(nums):
    skip, take = 0, 0
    for value in nums:
        skip, take = max(skip, take), skip + value
    return max(skip, take)

bruteForceCode:
def rob(nums):
    def best(i):
        if i >= len(nums):
            return 0
        return max(nums[i] + best(i + 2), best(i + 1))
    return best(0)
